## สรุปสาเหตุที่ดูแข็ง/ไม่ธรรมชาติ

1. **Steering ยังไม่ใช่ steering จริง**  
   front fork + handlebar + front wheel ถูก fix กับ frame จึงไม่มีการหมุนรอบ head tube axis เลย ทำให้เวลากดซ้าย/ขวา รถเอียงแต่ล้อหน้าไม่หันตาม

2. **Rider ถูก freeze หลายจุด**  
   pelvis, torso, shoulder, neck, แขน ไม่ขยับตาม pedal stroke มีแค่ขาที่ IK ไป pedal ทำให้ร่างกายดูเป็นหุ่นไม้

3. **Camera ไม่มี lag / damping**  
   กล้อง translate ตาม `player.x` ทันทีทุกเฟรม จึงรู้สึกกระตุกและ rigid

แนวทางคือเพิ่ม 3 ระบบ:

- **SteerPivot** ที่ head tube หมุน fork/handlebar/front wheel รอบ steer axis
- **CyclistRig** ที่ pelvis/torso/neck/arms เคลื่อนไหวตาม `crankAngle` และใช้ 2-bone IK ทั้งแขนและขา
- **Damped chase camera** ที่แยก lateral smoothing, look-ahead, apex, camera roll และ FOV

สมมติฐานในโค้ดนี้:

- `+X = ขวา`, `+Y = ขึ้น`, `+Z = หน้าของจักรยาน`
- ถ้าโมเดลของคุณหัน `-Z` ให้กลับ sign ของ `Z_AXIS`, `steerInput`, curvature และ bank ตามความเหมาะสม
- ทุกมุมเป็น radian

---

# 1. สูตรหลัก

## 1.1 Steering angle จาก curvature + lateral rate

ให้

\[
\kappa = \frac{\operatorname{wrap}(\psi_1-\psi_0)}{\Delta s}
\]

โดย

\[
\psi = \operatorname{atan2}(t_x,t_z)
\]

และ

\[
\delta_{\text{target}}
=
\operatorname{clamp}
\left(
\operatorname{atan}(L\kappa)
+
K_{\dot x}\operatorname{atan2}(\dot x, \max(v,2))
+
K_u u
,\ -\delta_{\max},\ \delta_{\max}
\right)
\]

จากนั้น smooth:

\[
\delta_{n+1}
=
\operatorname{damp}(\delta_n,\delta_{\text{target}},\lambda_{\text{steer}},dt)
\]

และหมุน steer pivot:

\[
q_{\text{steer}}
=
\operatorname{Quaternion.setFromAxisAngle}
(\hat a_{\text{headtube}},\delta)
\]

steer axis ที่ tilt จาก vertical:

\[
\hat a_{\text{headtube}}
=
\operatorname{normalize}(0,\cos\alpha,-\sin\alpha)
\]

โดย `alpha` คือ head tube rake จาก vertical เช่น 17°.

---

## 1.2 Pelvis / Torso organic motion

ให้ `theta = crankAngle`

\[
s=\sin\theta,\qquad c=\cos\theta
\]

\[
down = \frac{1-\cos(2\theta)}{2}
\]

 pelvis heave:

\[
y_{\text{pelvis}} = y_0 - A_{\text{heave}}\,down
\]

pelvis roll:

\[
roll_{\text{pelvis}} = -A_{\text{roll}}\,s
\]

pelvis yaw:

\[
yaw_{\text{pelvis}} = -A_{\text{yaw}}\,c
\]

torso counter-roll:

\[
roll_{\text{torso}}
=
-k_{\text{counterRoll}}\,roll_{\text{pelvis}}
+
A_{\text{torsoRollSway}}\,s
\]

torso pitch effort bobbing:

\[
pitch_{\text{torso}}
=
pitch_0
+
A_{\text{pitch}}\,down
\]

torso yaw:

\[
yaw_{\text{torso}}
=
-k_{\text{counterYaw}}\,yaw_{\text{pelvis}}
+
A_{\text{torsoYawSway}}\,s
\]

head gaze stabilization:

\[
neckPitch
=
-pitch_{\text{inherited}}K_{\text{gazePitch}}
+
A_{\text{nod}}\sin(2\theta)
\]

\[
neckYaw
=
-yaw_{\text{inherited}}K_{\text{gazeYaw}}
+
A_{\text{nodYaw}}\sin\theta
\]

\[
neckRoll
=
-roll_{\text{inherited}}K_{\text{gazeRoll}}
\]

---

## 1.3 2-bone IK สำหรับแขน/ขา

ให้ shoulder/hip = `A`, target = `T`, bone lengths = `L1`, `L2`

\[
\vec d = T-A
\]

\[
d = \operatorname{clamp}(|\vec d|,\ |L_1-L_2|+\epsilon,\ L_1+L_2-\epsilon)
\]

\[
a = \frac{L_1^2-L_2^2+d^2}{2d}
\]

\[
h = \sqrt{\max(0,L_1^2-a^2)}
\]

\[
E = A + \hat d\,a + \hat p\,h
\]

โดย `p` คือ pole vector projected ให้ตั้งฉากกับ `d`

---

# 2. Production-ready TypeScript / Three.js code

```ts
import * as THREE from 'three';

const Y_AXIS = new THREE.Vector3(0, 1, 0);
const Z_AXIS = new THREE.Vector3(0, 0, 1);

const clamp = THREE.MathUtils.clamp;
const damp = THREE.MathUtils.damp;

function wrapAngle(a: number): number {
  return Math.atan2(Math.sin(a), Math.cos(a));
}

function tangentYaw(t: THREE.Vector3): number {
  return Math.atan2(t.x, t.z);
}

function signedCurvature(
  prevTangent: THREE.Vector3,
  currTangent: THREE.Vector3,
  ds: number
): number {
  if (ds < 1e-4) return 0;
  return wrapAngle(tangentYaw(currTangent) - tangentYaw(prevTangent)) / ds;
}

function dampVec3(
  value: THREE.Vector3,
  target: THREE.Vector3,
  lambda: number,
  dt: number
): void {
  value.x = damp(value.x, target.x, lambda, dt);
  value.y = damp(value.y, target.y, lambda, dt);
  value.z = damp(value.z, target.z, lambda, dt);
}

/**
 * Two-bone IK.
 * Returns elbow/knee in outElbow and clamped end-effector in outEnd.
 */
function solveTwoBoneIK(
  rootA: THREE.Vector3,
  target: THREE.Vector3,
  l1: number,
  l2: number,
  pole: THREE.Vector3,
  outElbow: THREE.Vector3,
  outEnd: THREE.Vector3
): boolean {
  const toTarget = new THREE.Vector3().subVectors(target, rootA);
  let d = toTarget.length();

  if (d < 1e-6) {
    toTarget.set(0, 0, 1);
    d = 1e-6;
  }

  const dir = toTarget.clone().normalize();

  const dMin = Math.abs(l1 - l2) + 1e-4;
  const dMax = l1 + l2 - 1e-4;
  const reachable = d >= dMin && d <= dMax;
  const dClamped = clamp(d, dMin, dMax);

  const a = (l1 * l1 - l2 * l2 + dClamped * dClamped) / (2 * dClamped);
  const h = Math.sqrt(Math.max(0, l1 * l1 - a * a));

  const poleDir = new THREE.Vector3().subVectors(pole, rootA);
  poleDir.addScaledVector(dir, -poleDir.dot(dir));

  if (poleDir.lengthSq() < 1e-8) {
    poleDir.crossVectors(Z_AXIS, dir);
    if (poleDir.lengthSq() < 1e-8) {
      poleDir.crossVectors(Y_AXIS, dir);
    }
  }

  poleDir.normalize();

  outElbow
    .copy(rootA)
    .addScaledVector(dir, a)
    .addScaledVector(poleDir, h);

  outEnd.copy(rootA).addScaledVector(dir, dClamped);

  return reachable;
}

/**
 * Cylinder segment that always starts at group origin and extends along +Y.
 * Use setSegment(A, B) to position/orient it from A to B.
 */
class LimbSegment {
  readonly group = new THREE.Group();
  readonly mesh: THREE.Mesh;

  constructor(radius: number, material: THREE.Material) {
    const geo = new THREE.CylinderGeometry(radius, radius, 1, 10, 1, false);
    geo.translate(0, 0.5, 0);

    this.mesh = new THREE.Mesh(geo, material);
    this.mesh.castShadow = true;
    this.group.add(this.mesh);
  }

  setSegment(a: THREE.Vector3, b: THREE.Vector3): void {
    const dir = new THREE.Vector3().subVectors(b, a);
    const len = dir.length();

    this.group.position.copy(a);

    if (len < 1e-5) return;

    this.group.quaternion.setFromUnitVectors(Y_AXIS, dir.normalize());
    this.mesh.scale.set(1, len, 1);
  }
}
```

---

# 3. Dynamic handlebar / front wheel steering

```ts
export interface BicycleSteeringOptions {
  frameGroup: THREE.Group;

  /**
   * Head tube center in frame-group local space.
   */
  headTubeCenter: THREE.Vector3;

  /**
   * Head tube rake from vertical, radians.
   * Typical: 17 deg = THREE.MathUtils.degToRad(17).
   */
  headRakeFromVertical: number;

  /**
   * Front axle position relative to head tube center.
   * Example: (0, -0.55, 0.62)
   */
  frontAxleLocal: THREE.Vector3;

  wheelRadius: number;
  wheelbase: number;

  /**
   * Fork, handlebar, stem, etc. They should not be direct rigid children of frame.
   * This code re-parents them under steerPivot.
   */
  steeredParts: THREE.Object3D[];

  /**
   * Front wheel mesh. It will be re-parented to frontWheelSpin so it can spin.
   */
  frontWheelMesh: THREE.Object3D;

  gripLLocal: THREE.Vector3;
  gripRLocal: THREE.Vector3;

  maxSteer?: number;
  steerLambda?: number;
  lateralGain?: number;
  curvatureGain?: number;
  inputGain?: number;
}

export class BicycleSteeringRig {
  readonly steerPivot = new THREE.Group();
  readonly frontWheelSpin = new THREE.Group();
  readonly gripL = new THREE.Object3D();
  readonly gripR = new THREE.Object3D();

  readonly steerAxisLocal = new THREE.Vector3();

  steerAngle = 0;
  frontWheelAngle = 0;
  curvature = 0;

  private prevLateral = 0;
  private prevTangent = new THREE.Vector3(0, 0, 1);
  private hasPrev = false;

  private readonly wheelRadius: number;
  private readonly wheelbase: number;

  private readonly maxSteer: number;
  private readonly steerLambda: number;
  private readonly lateralGain: number;
  private readonly curvatureGain: number;
  private readonly inputGain: number;

  constructor(opts: BicycleSteeringOptions) {
    this.wheelRadius = opts.wheelRadius;
    this.wheelbase = opts.wheelbase;

    this.maxSteer = opts.maxSteer ?? THREE.MathUtils.degToRad(28);
    this.steerLambda = opts.steerLambda ?? 14;
    this.lateralGain = opts.lateralGain ?? 0.7;
    this.curvatureGain = opts.curvatureGain ?? 1.0;
    this.inputGain = opts.inputGain ?? 1.0;

    this.steerPivot.name = 'SteerPivot';
    this.steerPivot.position.copy(opts.headTubeCenter);

    opts.frameGroup.add(this.steerPivot);

    // Steering axis: mostly +Y, leaning back by rake angle.
    this.steerAxisLocal
      .set(
        0,
        Math.cos(opts.headRakeFromVertical),
        -Math.sin(opts.headRakeFromVertical)
      )
      .normalize();

    // Re-parent fork/handlebar/stem under steering pivot while preserving world transform.
    for (const part of opts.steeredParts) {
      this.steerPivot.attach(part);
    }

    // Front wheel must spin around axle, but also steer with the fork.
    this.frontWheelSpin.name = 'FrontWheelSpin';
    this.frontWheelSpin.position.copy(opts.frontAxleLocal);
    this.steerPivot.add(this.frontWheelSpin);
    this.frontWheelSpin.attach(opts.frontWheelMesh);

    // Hand targets for the rider IK.
    this.gripL.name = 'GripL';
    this.gripL.position.copy(opts.gripLLocal);
    this.steerPivot.add(this.gripL);

    this.gripR.name = 'GripR';
    this.gripR.position.copy(opts.gripRLocal);
    this.steerPivot.add(this.gripR);
  }

  update(
    dt: number,
    state: {
      tangent: THREE.Vector3;
      speed: number;
      lateral: number;
      steerInput: number;
    }
  ): void {
    const speed = Math.max(Math.abs(state.speed), 0.1);

    let lateralRate = 0;
    if (dt > 1e-5) {
      lateralRate = (state.lateral - this.prevLateral) / dt;
    }
    this.prevLateral = state.lateral;

    const tangent = state.tangent.clone().normalize();

    if (this.hasPrev) {
      const ds = Math.max(speed * dt, 1e-4);
      this.curvature = signedCurvature(this.prevTangent, tangent, ds);
    }

    this.prevTangent.copy(tangent);
    this.hasPrev = true;

    // Kinematic bicycle steering.
    const curvatureSteer =
      Math.atan(this.wheelbase * this.curvature) * this.curvatureGain;

    // Steering from lateral motion rate.
    const lateralSteer =
      this.lateralGain *
      Math.atan2(lateralRate, Math.max(2.0, speed));

    // Player input.
    const inputSteer =
      this.inputGain * clamp(state.steerInput, -1, 1);

    const target = clamp(
      curvatureSteer + lateralSteer + inputSteer,
      -this.maxSteer,
      this.maxSteer
    );

    this.steerAngle = damp(this.steerAngle, target, this.steerLambda, dt);

    this.steerPivot.quaternion.setFromAxisAngle(
      this.steerAxisLocal,
      this.steerAngle
    );

    // Wheel spin around local X axis.
    this.frontWheelAngle += (state.speed / this.wheelRadius) * dt;
    this.frontWheelSpin.rotation.x = this.frontWheelAngle;
  }
}
```

> สำคัญ: ถ้า handlebar/fork เดิมถูก parent อยู่ใต้ `frameGroup` ตรง ๆ ต้องย้ายมาใต้ `steerPivot` ตามโค้ดข้างบน  
> ถ้า front wheel ถูกฝังอยู่ใต้ fork อยู่แล้ว โค้ด `frontWheelSpin.attach(frontWheelMesh)` จะย้ายมันออกมาอยู่ใต้ spin pivot โดยรักษา world transform

---

# 4. Organic cyclist rig

```ts
export interface CyclistDynamics {
  heave: number;
  pelvisRoll: number;
  pelvisYaw: number;
  pelvisSway: number;
  pelvisPitch: number;

  torsoPitch: number;
  torsoCounterRoll: number;
  torsoRollSway: number;
  torsoCounterYaw: number;
  torsoYawSway: number;
  torsoLateral: number;

  gazePitch: number;
  gazeYaw: number;
  gazeRoll: number;

  nod: number;
  nodYaw: number;
  headNod: number;
  headYaw: number;
}

export const DEFAULT_CYCLIST_DYNAMICS: CyclistDynamics = {
  heave: 0.018,
  pelvisRoll: 0.035,
  pelvisYaw: 0.025,
  pelvisSway: 0.006,
  pelvisPitch: 0.008,

  torsoPitch: 0.045,
  torsoCounterRoll: 0.65,
  torsoRollSway: 0.015,
  torsoCounterYaw: 0.35,
  torsoYawSway: 0.02,
  torsoLateral: 0.008,

  gazePitch: 0.85,
  gazeYaw: 0.82,
  gazeRoll: 0.78,

  nod: 0.012,
  nodYaw: 0.018,
  headNod: 0.01,
  headYaw: 0.012
};

export interface CyclistRigOptions {
  basePelvis: THREE.Vector3;

  torsoBaseOffset: THREE.Vector3;
  torsoBasePitch: number;

  neckOffset: THREE.Vector3;

  shoulderL: THREE.Vector3;
  shoulderR: THREE.Vector3;

  hipL: THREE.Vector3;
  hipR: THREE.Vector3;

  armUpper: number;
  armFore: number;

  thigh: number;
  shin: number;

  material?: THREE.Material;
  dynamics?: Partial<CyclistDynamics>;
}

export class CyclistRig {
  readonly root = new THREE.Group();

  readonly pelvis = new THREE.Group();
  readonly torso = new THREE.Group();
  readonly neck = new THREE.Group();
  readonly head = new THREE.Group();

  readonly shoulderL = new THREE.Object3D();
  readonly shoulderR = new THREE.Object3D();

  readonly hipL = new THREE.Object3D();
  readonly hipR = new THREE.Object3D();

  readonly upperArmL: LimbSegment;
  readonly foreArmL: LimbSegment;
  readonly upperArmR: LimbSegment;
  readonly foreArmR: LimbSegment;

  readonly thighL: LimbSegment;
  readonly shinL: LimbSegment;
  readonly thighR: LimbSegment;
  readonly shinR: LimbSegment;

  readonly elbowJointL: THREE.Mesh;
  readonly elbowJointR: THREE.Mesh;
  readonly kneeJointL: THREE.Mesh;
  readonly kneeJointR: THREE.Mesh;

  private readonly basePelvis = new THREE.Vector3();
  private readonly torsoBaseOffset = new THREE.Vector3();
  private readonly torsoBasePitch: number;

  private readonly armUpper: number;
  private readonly armFore: number;
  private readonly thighLength: number;
  private readonly shinLength: number;

  private readonly dynamics: CyclistDynamics;

  constructor(parent: THREE.Object3D, opts: CyclistRigOptions) {
    this.basePelvis.copy(opts.basePelvis);
    this.torsoBaseOffset.copy(opts.torsoBaseOffset);
    this.torsoBasePitch = opts.torsoBasePitch;

    this.armUpper = opts.armUpper;
    this.armFore = opts.armFore;
    this.thighLength = opts.thigh;
    this.shinLength = opts.shin;

    this.dynamics = {
      ...DEFAULT_CYCLIST_DYNAMICS,
      ...(opts.dynamics ?? {})
    };

    parent.add(this.root);

    const material =
      opts.material ??
      new THREE.MeshStandardMaterial({
        color: 0x3f6fa8,
        roughness: 0.8,
        metalness: 0.05
      });

    // pelvis
    this.pelvis.name = 'Pelvis';
    this.pelvis.position.copy(this.basePelvis);
    this.pelvis.rotation.order = 'YXZ';
    this.root.add(this.pelvis);

    const pelvisMesh = new THREE.Mesh(
      new THREE.SphereGeometry(0.18, 16, 12),
      material
    );
    pelvisMesh.scale.set(1.1, 0.72, 0.92);
    pelvisMesh.castShadow = true;
    this.pelvis.add(pelvisMesh);

    // torso
    this.torso.name = 'Torso';
    this.torso.position.copy(this.torsoBaseOffset);
    this.torso.rotation.set(this.torsoBasePitch, 0, 0, 'YXZ');
    this.torso.rotation.order = 'YXZ';
    this.pelvis.add(this.torso);

    const torsoLength = Math.max(
      opts.shoulderL.y,
      opts.shoulderR.y,
      0.5
    );

    const torsoGeo = new THREE.CylinderGeometry(
      0.16,
      0.21,
      torsoLength,
      12,
      1,
      false
    );
    torsoGeo.translate(0, torsoLength * 0.5, 0);

    const torsoMesh = new THREE.Mesh(torsoGeo, material);
    torsoMesh.castShadow = true;
    this.torso.add(torsoMesh);

    // neck / head
    this.neck.name = 'Neck';
    this.neck.position.copy(opts.neckOffset);
    this.neck.rotation.order = 'YXZ';
    this.torso.add(this.neck);

    this.head.name = 'Head';
    this.neck.add(this.head);

    const headMesh = new THREE.Mesh(
      new THREE.SphereGeometry(0.15, 16, 12),
      material
    );
    headMesh.scale.set(0.9, 1.08, 1.0);
    headMesh.castShadow = true;
    this.head.add(headMesh);

    // shoulder markers
    this.shoulderL.name = 'ShoulderL';
    this.shoulderL.position.copy(opts.shoulderL);
    this.torso.add(this.shoulderL);

    this.shoulderR.name = 'ShoulderR';
    this.shoulderR.position.copy(opts.shoulderR);
    this.torso.add(this.shoulderR);

    // hip markers
    this.hipL.name = 'HipL';
    this.hipL.position.copy(opts.hipL);
    this.pelvis.add(this.hipL);

    this.hipR.name = 'HipR';
    this.hipR.position.copy(opts.hipR);
    this.pelvis.add(this.hipR);

    // limbs
    this.upperArmL = new LimbSegment(0.045, material);
    this.foreArmL = new LimbSegment(0.04, material);
    this.upperArmR = new LimbSegment(0.045, material);
    this.foreArmR = new LimbSegment(0.04, material);

    this.thighL = new LimbSegment(0.07, material);
    this.shinL = new LimbSegment(0.055, material);
    this.thighR = new LimbSegment(0.07, material);
    this.shinR = new LimbSegment(0.055, material);

    this.root.add(
      this.upperArmL.group,
      this.foreArmL.group,
      this.upperArmR.group,
      this.foreArmR.group,
      this.thighL.group,
      this.shinL.group,
      this.thighR.group,
      this.shinR.group
    );

    // joints
    const jointGeo = new THREE.SphereGeometry(0.045, 10, 8);
    const jointMat = new THREE.MeshStandardMaterial({
      color: 0x25364d,
      roughness: 0.8
    });

    this.elbowJointL = new THREE.Mesh(jointGeo, jointMat);
    this.elbowJointR = new THREE.Mesh(jointGeo, jointMat);
    this.kneeJointL = new THREE.Mesh(jointGeo, jointMat);
    this.kneeJointR = new THREE.Mesh(jointGeo, jointMat);

    this.root.add(
      this.elbowJointL,
      this.elbowJointR,
      this.kneeJointL,
      this.kneeJointR
    );
  }

  update(
    dt: number,
    state: {
      crankAngle: number;
      speed: number;

      gripL: THREE.Object3D;
      gripR: THREE.Object3D;

      pedalL: THREE.Object3D;
      pedalR: THREE.Object3D;
    }
  ): void {
    const d = this.dynamics;
    const theta = state.crankAngle;

    const s = Math.sin(theta);
    const c = Math.cos(theta);
    const down = 0.5 - 0.5 * Math.cos(2 * theta);

    // ------------------------------------------------------------
    // 1. Pelvis dynamic sway
    // ------------------------------------------------------------
    const pelvicRoll = -d.pelvisRoll * s;
    const pelvicYaw = -d.pelvisYaw * c;
    const pelvicPitch = d.pelvisPitch * down;
    const pelvicHeave = -d.heave * down;

    this.pelvis.position.copy(this.basePelvis);
    this.pelvis.position.y += pelvicHeave;
    this.pelvis.position.x += d.pelvisSway * s;

    this.pelvis.rotation.set(
      pelvicPitch,
      pelvicYaw,
      pelvicRoll,
      'YXZ'
    );

    // ------------------------------------------------------------
    // 2. Torso counter-roll / pitch bobbing / lateral sway
    // ------------------------------------------------------------
    const torsoPitch =
      this.torsoBasePitch + d.torsoPitch * down;

    const torsoRoll =
      -pelvicRoll * d.torsoCounterRoll +
      d.torsoRollSway * s;

    const torsoYaw =
      -pelvicYaw * d.torsoCounterYaw +
      d.torsoYawSway * s;

    this.torso.position.copy(this.torsoBaseOffset);
    this.torso.position.x += d.torsoLateral * s;

    this.torso.rotation.set(
      torsoPitch,
      torsoYaw,
      torsoRoll,
      'YXZ'
    );

    // ------------------------------------------------------------
    // 3. Head gaze stabilization + subtle nod
    // ------------------------------------------------------------
    const inheritedPitch = pelvicPitch + torsoPitch;
    const inheritedYaw = pelvicYaw + torsoYaw;
    const inheritedRoll = pelvicRoll + torsoRoll;

    const neckPitch =
      -inheritedPitch * d.gazePitch +
      d.nod * Math.sin(2 * theta);

    const neckYaw =
      -inheritedYaw * d.gazeYaw +
      d.nodYaw * Math.sin(theta);

    const neckRoll =
      -inheritedRoll * d.gazeRoll;

    this.neck.rotation.set(
      neckPitch,
      neckYaw,
      neckRoll,
      'YXZ'
    );

    this.head.rotation.set(
      d.headNod * Math.sin(2 * theta + 0.6),
      d.headYaw * Math.sin(theta),
      0,
      'YXZ'
    );

    // Update matrices before reading shoulders / hips / grips / pedals.
    this.root.updateWorldMatrix(true, true);

    // ------------------------------------------------------------
    // 4. Arms: 2-bone IK from shoulder -> handlebar grip
    // ------------------------------------------------------------
    const shoulderLWorld = new THREE.Vector3();
    const shoulderRWorld = new THREE.Vector3();
    const handLWorld = new THREE.Vector3();
    const handRWorld = new THREE.Vector3();

    this.shoulderL.getWorldPosition(shoulderLWorld);
    this.shoulderR.getWorldPosition(shoulderRWorld);

    state.gripL.getWorldPosition(handLWorld);
    state.gripR.getWorldPosition(handRWorld);

    this.root.worldToLocal(shoulderLWorld);
    this.root.worldToLocal(shoulderRWorld);
    this.root.worldToLocal(handLWorld);
    this.root.worldToLocal(handRWorld);

    const elbowL = new THREE.Vector3();
    const elbowR = new THREE.Vector3();
    const endL = new THREE.Vector3();
    const endR = new THREE.Vector3();

    // Elbows point outward/back/down.
    const poleL = shoulderLWorld
      .clone()
      .add(new THREE.Vector3(-0.55, -0.25, -0.25));

    const poleR = shoulderRWorld
      .clone()
      .add(new THREE.Vector3(0.55, -0.25, -0.25));

    solveTwoBoneIK(
      shoulderLWorld,
      handLWorld,
      this.armUpper,
      this.armFore,
      poleL,
      elbowL,
      endL
    );

    solveTwoBoneIK(
      shoulderRWorld,
      handRWorld,
      this.armUpper,
      this.armFore,
      poleR,
      elbowR,
      endR
    );

    this.upperArmL.setSegment(shoulderLWorld, elbowL);
    this.foreArmL.setSegment(elbowL, endL);

    this.upperArmR.setSegment(shoulderRWorld, elbowR);
    this.foreArmR.setSegment(elbowR, endR);

    this.elbowJointL.position.copy(elbowL);
    this.elbowJointR.position.copy(elbowR);

    // ------------------------------------------------------------
    // 5. Legs: 2-bone IK from dynamic hip -> pedal
    // ------------------------------------------------------------
    const hipLWorld = new THREE.Vector3();
    const hipRWorld = new THREE.Vector3();
    const pedalLWorld = new THREE.Vector3();
    const pedalRWorld = new THREE.Vector3();

    this.hipL.getWorldPosition(hipLWorld);
    this.hipR.getWorldPosition(hipRWorld);

    state.pedalL.getWorldPosition(pedalLWorld);
    state.pedalR.getWorldPosition(pedalRWorld);

    this.root.worldToLocal(hipLWorld);
    this.root.worldToLocal(hipRWorld);
    this.root.worldToLocal(pedalLWorld);
    this.root.worldToLocal(pedalRWorld);

    const kneeL = new THREE.Vector3();
    const kneeR = new THREE.Vector3();
    const ankleL = new THREE.Vector3();
    const ankleR = new THREE.Vector3();

    // Knees point forward.
    const poleKneeL = hipLWorld
      .clone()
      .add(new THREE.Vector3(0, 0, 0.8));

    const poleKneeR = hipRWorld
      .clone()
      .add(new THREE.Vector3(0, 0, 0.8));

    solveTwoBoneIK(
      hipLWorld,
      pedalLWorld,
      this.thighLength,
      this.shinLength,
      poleKneeL,
      kneeL,
      ankleL
    );

    solveTwoBoneIK(
      hipRWorld,
      pedalRWorld,
      this.thighLength,
      this.shinLength,
      poleKneeR,
      kneeR,
      ankleR
    );

    this.thighL.setSegment(hipLWorld, kneeL);
    this.shinL.setSegment(kneeL, ankleL);

    this.thighR.setSegment(hipRWorld, kneeR);
    this.shinR.setSegment(kneeR, ankleR);

    this.kneeJointL.position.copy(kneeL);
    this.kneeJointR.position.copy(kneeR);
  }
}
