# 5. Natural damped chase camera

```ts
export interface NaturalChaseCameraOptions {
  distance: number;
  height: number;

  lateralGain: number;
  lateralLambda: number;

  positionLambda: number;

  lookAhead: number;
  lookHeight: number;

  apexGain: number;
  maxApex: number;
  lookLambda: number;

  bankRollGain: number;
  bankRollSign: number;
  rollLambda: number;

  baseFov: number;
  speedFov: number;
  boostFov: number;
  fovLambda: number;
}

export const DEFAULT_CHASE_CAMERA_OPTIONS: NaturalChaseCameraOptions = {
  distance: 8.2,
  height: 3.6,

  lateralGain: 1.15,
  lateralLambda: 2.2,

  positionLambda: 5.0,

  lookAhead: 6.0,
  lookHeight: 0.9,

  apexGain: 18.0,
  maxApex: 2.8,
  lookLambda: 6.0,

  bankRollGain: 0.18,
  bankRollSign: 1.0,
  rollLambda: 4.0,

  baseFov: 60,
  speedFov: 8,
  boostFov: 12,
  fovLambda: 3.0
};

export class NaturalChaseCamera {
  private readonly positionSmooth = new THREE.Vector3();
  private readonly lookSmooth = new THREE.Vector3();

  private lateralSmooth = 0;
  private rollSmooth = 0;
  private fovSmooth: number;

  private initialized = false;

  private readonly opts: NaturalChaseCameraOptions;

  constructor(
    readonly camera: THREE.PerspectiveCamera,
    opts?: Partial<NaturalChaseCameraOptions>
  ) {
    this.opts = {
      ...DEFAULT_CHASE_CAMERA_OPTIONS,
      ...(opts ?? {})
    };

    this.fovSmooth = this.opts.baseFov;
  }

  update(
    dt: number,
    state: {
      position: THREE.Vector3;
      tangent: THREE.Vector3;

      lateral: number;
      bank: number;

      speed: number;
      maxSpeed: number;
      boost: number;

      curvature: number;
    }
  ): void {
    const opts = this.opts;

    const tangent = state.tangent.clone().normalize();

    // Right vector for forward = +Z, up = +Y.
    const right = new THREE.Vector3()
      .crossVectors(Y_AXIS, tangent)
      .normalize();

    // Separate lateral smoothing:
    // bike can move laterally before camera catches it.
    this.lateralSmooth = damp(
      this.lateralSmooth,
      state.lateral,
      opts.lateralLambda,
      dt
    );

    const targetPosition = state.position
      .clone()
      .addScaledVector(tangent, -opts.distance)
      .addScaledVector(Y_AXIS, opts.height)
      .addScaledVector(
        right,
        this.lateralSmooth * opts.lateralGain
      );

    // Apex look-ahead: look inside the curve.
    const apexOffset = clamp(
      state.curvature * opts.apexGain,
      -opts.maxApex,
      opts.maxApex
    );

    const targetLook = state.position
      .clone()
      .addScaledVector(tangent, opts.lookAhead)
      .addScaledVector(right, apexOffset)
      .addScaledVector(Y_AXIS, opts.lookHeight);

    if (!this.initialized) {
      this.positionSmooth.copy(targetPosition);
      this.lookSmooth.copy(targetLook);
      this.initialized = true;
    }

    dampVec3(
      this.positionSmooth,
      targetPosition,
      opts.positionLambda,
      dt
    );

    dampVec3(
      this.lookSmooth,
      targetLook,
      opts.lookLambda,
      dt
    );

    // Dutch roll / horizon banking.
    const targetRoll =
      state.bank *
      opts.bankRollGain *
      opts.bankRollSign;

    this.rollSmooth = damp(
      this.rollSmooth,
      targetRoll,
      opts.rollLambda,
      dt
    );

    this.camera.position.copy(this.positionSmooth);

    const viewDir = new THREE.Vector3()
      .subVectors(this.lookSmooth, this.positionSmooth)
      .normalize();

    if (viewDir.lengthSq() < 1e-8) {
      viewDir.set(0, 0, 1);
    }

    const cameraUp = Y_AXIS.clone().applyAxisAngle(
      viewDir,
      this.rollSmooth
    );

    this.camera.up.copy(cameraUp.normalize());
    this.camera.lookAt(this.lookSmooth);

    // Speed + boost dynamic FOV.
    const speed01 = clamp(
      Math.abs(state.speed) / Math.max(state.maxSpeed, 1e-3),
      0,
      1
    );

    const boost01 = clamp(state.boost, 0, 1);

    const targetFov =
      opts.baseFov +
      opts.speedFov * speed01 +
      opts.boostFov * boost01;

    this.fovSmooth = damp(
      this.fovSmooth,
      targetFov,
      opts.fovLambda,
      dt
    );

    this.camera.fov = this.fovSmooth;
    this.camera.updateProjectionMatrix();
  }
}
