# 6. Integration order ใน game loop

```ts
export interface BikeUpdateState {
  position: THREE.Vector3;
  tangent: THREE.Vector3;

  lateral: number;
  speed: number;
  maxSpeed: number;

  steerInput: number;
  crankAngle: number;
  boost: number;
}

export function updateBikeRig(
  dt: number,
  state: BikeUpdateState,
  bikeRoot: THREE.Object3D,
  rollPivot: THREE.Object3D,
  steering: BicycleSteeringRig,
  cyclist: CyclistRig,
  chaseCamera: NaturalChaseCamera,
  pedalL: THREE.Object3D,
  pedalR: THREE.Object3D
): void {
  const tangent = state.tangent.clone().normalize();

  // 1. Place and orient bike root.
  bikeRoot.position.copy(state.position);
  bikeRoot.quaternion.setFromUnitVectors(Z_AXIS, tangent);

  // 2. Steering first, because it computes curvature.
  steering.update(dt, {
    tangent,
    speed: state.speed,
    lateral: state.lateral,
    steerInput: state.steerInput
  });

  // 3. Dynamic banking.
  // Positive curvature = turn right. Right lean should be negative Z rotation.
  const bankTarget = clamp(
    -Math.atan(
      (state.speed * state.speed * steering.curvature) / 9.81
    ) * 0.85,
    THREE.MathUtils.degToRad(-32),
    THREE.MathUtils.degToRad(32)
  );

  rollPivot.rotation.z = damp(
    rollPivot.rotation.z,
    bankTarget,
    8,
    dt
  );

  // 4. Rider IK. Grips already include steering rotation.
  cyclist.update(dt, {
    crankAngle: state.crankAngle,
    speed: state.speed,
    gripL: steering.gripL,
    gripR: steering.gripR,
    pedalL,
    pedalR
  });

  // 5. Camera after bike/rider transforms.
  chaseCamera.update(dt, {
    position: state.position,
    tangent,
    lateral: state.lateral,
    bank: rollPivot.rotation.z,
    speed: state.speed,
    maxSpeed: state.maxSpeed,
    boost: state.boost,
    curvature: steering.curvature
  });
}
